  <script type="text/ng-template" id="ysRecommendationLotInfoItemTemplate">
<div data-ng-repeat="lotinfoitem in lotinfoitems" class="itemContainer newItemContainer">
  <a ng-href="{{::lotinfoitem.url}}" ys-ge-click="" ge-data="{{::lotinfoitem.gepcTrack}}" ga-data="{{::lotinfoitem.ga4pcTrack}}" ng-click="onClickProduct($event, lotinfoitem.ga4pcTrack,&#039;widget3&#039;)">
