          <span class="textMostPopular flex-auto" ng-if="lotinfoitem.isMostPopular">الأكثر شعبية</span>
          <span class="textLimitedDeal flex-auto" ng-if="lotinfoitem.isLimitedDeal">تخفيضات سريعة</span>
          <span class="textAdventCalendar flex-auto" ng-if="lotinfoitem.isEarlyBird">EARLY BIRD</span>
          <span class="textNewArrival flex-auto" ng-if="lotinfoitem.isTrendingNew">الرائج الآن</span>
          <span class="textMustTry flex-auto" ng-if="lotinfoitem.isMustTry">يجب أن تجربها</span>
          <span class="textExclusiveSale flex-auto" ng-if="lotinfoitem.isExclusiveSale">بيع حصري</span>
          <span class="textEcoFriendly flex-auto" ng-if="lotinfoitem.isEcoFriendly">صديقة للبيئة</span>
          <span class="textFixedPrice flex-auto" ng-if="lotinfoitem.isFixedPrice">إنخفاض الأسعار</span>
          
