      <span class="itemSaver" ng-class="{&#039;activePulse&#039;:isSavedItem(lotinfoitem.product.productId, lotinfoitem.childProductIds)}" ng-click="onSaveSelectedProductOption($event, lotinfoitem.product.productId, lotinfoitem.childProductIds)"><span class="transit iconWrapper"><span class="animated icon icon-save-items"></span></span></span>
      
    </div>
