  <script type="text/ng-template" id="/panel/CookiesManage.html">
  
  <md-dialog>
    <form name="cookiesForm">
      <md-toolbar>
        <div class="md-toolbar-tools toolbarGradient">
          <h2>تفضيلات ملفات تعريف الارتباط</h2>
        </div>
      </md-toolbar>
      <md-dialog-content>
        <div class="md-dialog-content">
          نحن نستخدم ملفات تعريف الارتباط أو الكوكيز للبيانات لتخزين تفضيلاتك عبر الإنترنت وجمع المعلومات. يمكنك استخدام هذه الواجهة لتمكين أو تعطيل مجموعات من ملفات تعريف الارتباط ذات وظائف مختلفة.<br/><br/>
          <div class="emailPreference">
            <md-switch class="md-primary disabledStyle" ng-disabled="true" ng-model="manageCookieForm.strictly"><b>ملفات تعريف ارتباط YesStyle</b></md-switch>
            <p>ملفات تعريف الارتباط أو الكوكيز هذه مطلوبة لاستخدام ميزات موقع الويب الأساسية ويتم تمكينها تلقائيًا عند استخدام الموقع. كما أنها تتيح أيضًا استخدام عمليات حقيبة التسوق والخروج، وتساعد في المسائل التنظيمية والأمنية، وتقيس حركة المرور والزيارات، وتستعيد معلومات الطلب الخاصة بالعمولات التابعة. نحن نستخدم المعلومات التي تم جمعها لتقييم وتحسين أداء تجربة التسوق الخاصة بك.</p>
            <md-switch class="md-primary" ng-model="manageCookieForm.advertising"><b>ملفات تعريف الارتباط التسويقية</b></md-switch>
            <p>تُستخدم ملفات تعريف الارتباط أو الكوكيز لتقديم إعلانات أكثر صلة بك وباهتماماتك. يتم وضع ملفات تعريف الارتباط التسويقية بواسطة موفري خدمات خارجيين بإذن منا، ويمكن مشاركة أي معلومات تم جمعها مع مؤسسات أخرى مثل الناشرين أو المعلنين.</p>
            <md-switch class="md-primary" ng-model="manageCookieForm.statistics"><b>ملفات تعريف الارتباط الإحصائية</b></md-switch>
            <p>تمكننا ملفات تعريف الارتباط أو الكوكيز هذه من تقديم خدمات أفضل بناءً على كيفية استخدام المستخدمين لموقعنا الإلكتروني، وتسمح لنا بتحسين ميزاتنا لتقديم تجربة مستخدم أفضل.المعلومات التي تم جمعها مجمّعة ومجهولة المصدر.</p>
            
              <md-switch class="md-primary" ng-model="manageCookieForm.preference"><b>ملفات تعريف الارتباط المفضلة</b></md-switch>
              <p>تمكننا ملفات تعريف الارتباط أو الكوكيز هذه من تزويدك بتجربة مخصصة بناءً على تفضيلات ومعلومات التسوق الخاصة بك، مثل منطقتك ولغتك المفضلة وسجل البحث. إنها تسمح لنا بتزويدك بتجربة مستخدم أفضل. يتم وضع ملفات تعريف الارتباط المفضلة بواسطة موفري خدمات خارجيين بإذن منا، ويمكن مشاركة أي معلومات تم جمعها مع مقدمي خدمات الطرف الثالث هؤلاء.</p>
            
          </div>
        </div>
      </md-dialog-content>
      <md-dialog-actions class="layout-row">
        <md-button class="md-raised basicButton" ng-click="saveSettings(&quot;https://www.yesstyle.com/rest/cookies/v1/update-cookie-manage&quot;)">قبول المحدد</md-button>
        <md-button class="md-raised md-primary primaryButton" ng-click="acceptAll(&quot;https://www.yesstyle.com/rest/cookies/v1/update-cookie-manage&quot;)">قبول الكل</md-button>
      </md-dialog-actions>
    </form>
  </md-dialog>

  </script>



