<form name="shippingrate" class="layout-margin layout-row layout-align-center-center" style="background-color:#EEE; margin:0">
    <!-- Hide Orange note when select menu is active -->
    	<style> 
		.md-active dfn {  display: none; } 
		[name="shippingrate"] md-select:not(.roundCorner md-select):not(md-input-container md-select) { margin-block: 8px !important; }
		[name="shippingrate"] md-select:not(.roundCorner md-select):not(md-input-container md-select) md-select-value { background: #fff !important; min-height: 32px !important; }
	</style>
    <span style="line-height:2.2em; margin-right:0">وجهة الشحن:</span>
    <!-- country code value reference: https://countrycode.org/ -->
    <md-select ng-model="regionSelection.code" placeholder="اختر المنطقة">
        <md-option ng-repeat="region in ysShipmentRate | orderBy:'name'" value="{{region.code}}">
            {{regionname.table[region.code]}}
            <dfn style="color:orange" ng-if="region.code=='tr'">*</dfn>
            <dfn style="color:#00f" ng-if="region.code=='mx' || region.code=='th' || region.code=='hk'">*</dfn>
            <dfn style="color:purple" ng-if="region.code=='mx' || region.code=='th'">*</dfn>
            <dfn style="color:red" ng-if="region.code=='us'">*</dfn>
            <dfn style="color:#FF00FF" ng-if="['be','fr','de','lu','nl','dk','ie','pl','se'].includes(region.code)">*</dfn>
        </md-option>
        <md-option value="">قائمة جميع</md-option>
    </md-select>
</form>
<table cellpadding="1" cellspacing="0" border="0" width="100%" ng-init='
shipmentName.table={
"SF":"سريع / SF استلام سريع ذاتي",
"Express":"سريع",
"Expedited":"عاجل",
"Premium Standard":"قياسي مميز",
"Standard":"قياسي"
}'>
    <tr>
        <td bgcolor="#999999">
            <table class="helptable xs-break centercell" cellpadding="5" cellspacing="1" border="0" width="100%">
                <thead>
                <tr>
                    <th width="20%" ng-if="regionSelection.code==''">المنطقة</th>
                    <th>الشحن <span class="nowrap">
                        الطريقة
                        <dfn style="color:orange" ng-if="regionSelection.code=='tr'">*</dfn>
                        <dfn style="color:#00f" ng-if="regionSelection.code=='mx' || regionSelection.code=='th' || regionSelection.code=='hk'">*</dfn>
                        <dfn style="color:purple" ng-if="regionSelection.code=='mx'|| regionSelection.code=='th'">*</dfn>
                        <dfn style="color:red" ng-if="regionSelection.code=='us'">*</dfn>
                        <dfn style="color:#FF00FF" ng-if="['be','fr','de','lu','nl','dk','ie','pl','se'].includes(regionSelection.code)">*</dfn>
                        </span>
                    </th>
                    <th width="40%">سعر الشحن <span class="remark nowrap">(اجمالى الطلب<font color="#0000ff">#</font>)</span></th>
                    <th>
                        وقت الشحن التقديري
                        <!-- <dfn style="color:red">*</dfn> -->
                        <span class="remark nowrap">(أيام عمل)</span>
                    </th>
                    <th>رمز التتبع</th>
                </tr>
                </thead>
                <tbody class="slideDown" ng-class="$even?'odd':'even'" ng-repeat="shipmentRate in ysShipmentRate | filter:regionSelection:true | orderBy:'name' as results track by shipmentRate.code" ng-if="regionSelection.code!=''">
                <tr ng-repeat="method in shipmentRate.method" ng-class="{shipmin : shipmentRate.method.length==1}">

                    <td class="block" title="طريقة الشحن">{{shipmentName.table[method.name]}}<dfn style="color:#093" ng-if="regionSelection.code=='au' && method.name=='Premium Standard'">*</dfn></td>
                    <td class="block" title="Shipping Rate (Order Total)">
                        <div class="totalrate">
                            <table class="helptable unbreak" cellpadding="5" cellspacing="1" border="0" width="100%">
                                <tr valign="top" ng-if="method.rate.greater">
                                    <td width="30%"><font ng-class="{free: method.rate.greater.rate=='Free'}" ng-bind-html="method.rate.greater.rate=='Free' ? 'مجاناً' : method.rate.greater.rate=='Unavailable' ? 'غير متوفره' : method.rate.greater.rate"></font></td>
                                    <td width="70%" class="remark">(<span ng-bind-html="method.rate.greater.threshold"></span> أو أكثر)</td></tr>
                                <tr valign="top" ng-if="method.rate.upto">
                                    <td width="30%" ng-bind-html="method.rate.upto.rate"></td>
                                    <td width="70%" class="remark">(<span ng-bind-html="method.rate.upto.threshold"></span>)</td></tr>
                                <tr align="top" ng-if="method.rate.between" ng-repeat="between in method.rate.between track by $index">
                                    <td ng-bind-html="between.rate"></td>
                                    <td class="remark">(بين <span ng-bind-html="(between.threshold && ($index == (method.rate.between.length - 1)))? method.rate.below.threshold : method.rate.between.length>1 ? method.rate.between[$index+1].threshold : method.rate.below.threshold"></span  و <span ng-bind-html="between.threshold? between.threshold : method.rate.greater.threshold"></span>)</td></tr>
                                <tr valign="top" ng-if="method.rate.below">
                                    <td ng-bind-html="method.rate.below.rate"></td>
                                    <td class="remark">(أقل من <span ng-bind-html="method.rate.below.threshold"></span>)</td></tr>
                            </table>
                        </div>
                    </td>
                    <td class="block" title="وقت الشحن التقديري" sb="working days">{{method.time}}</td>
                    <td class="block" title="Tracking Code">{{method.tracking ? "&#10003;" : "&times;"}}</td>
                </tr>
                </tbody>
                <tbody class="slideDown" ng-class="$even?'odd':'even'" ng-repeat="(code,shipmentRate) in ysRegionGroup" ng-if="regionSelection.code==''">
