                        <dfn style="color:red" ng-if="code=='us'">*</dfn>
                        <dfn style="color:#FF00FF" ng-if="['be','fr','de','lu','nl','dk','ie','pl','se'].includes(code)">*</dfn>
                    </td>
                    <td class="block" title="طريقة الشحن">{{shipmentName.table[method.name]}}<dfn style="color:#093" ng-if="code=='au' && method.name=='Premium Standard'">*</dfn></td>
                    <td class="block" title="Shipping Rate (Order Total)">
                        <div class="totalrate">
                            <table class="helptable unbreak" cellpadding="5" cellspacing="1" border="0" width="100%">
                                <tr valign="top" ng-if="method.rate.greater">
