                                    <td class="remark">(بين <span ng-bind-html="(between.threshold && ($index == (method.rate.between.length - 1)))? method.rate.below.threshold : method.rate.between.length>1 ? method.rate.between[$index+1].threshold : method.rate.below.threshold"></span> و <span ng-bind-html="between.threshold? between.threshold : method.rate.greater.threshold"></span>)</td></tr>
